L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_fTitleTalkTime = 0.01
L30_1.m_SubTitle_KOREA = "<color=#ffd34c>나</color>: 너, 내가 다시는 연락하지 말라고 했지?\n<color=#ffd34c>나</color>: 내 말이 말 같지 않아? 이 ip는 또 어떻게 알아낸 건데?"
L30_1.m_fSubTitleTalkTime = 0.01
L30_1.m_SubTitle_JPN = "<color=#ffd34c>自分</color>：あなたね、二度と連絡してこないでって言ったはずよ？\n<color=#ffd34c>自分</color>：冗談だと思ってるの？　このIPはどうして知ってるわけ？"
L30_1.m_SubTitle_ENG = [[
<color=#ffd34c>Me</color>: Hey. I told you never to contact me again.
<color=#ffd34c>Me</color>: Do you think I wasn't serious? And how the heck did you even find this IP?]]
L30_1.m_SubTitle_TWN = "<color=#ffd34c>我</color>：我不是說過別再聯絡我了嗎？\n<color=#ffd34c>我</color>：你把我的話當耳邊風？你又是怎麼知道這個ip的？"
L30_1.m_SubTitle_DEU = [[
<color=#ffd34c>Me</color>: Hey. I told you never to contact me again.
<color=#ffd34c>Me</color>: Do you think I wasn't serious? And how the heck did you even find this IP?]]
L30_1.m_SubTitle_FRA = [[
<color=#ffd34c>Me</color>: Hey. I told you never to contact me again.
<color=#ffd34c>Me</color>: Do you think I wasn't serious? And how the heck did you even find this IP?]]
