L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_fTitleTalkTime = 0.01
L31_1.m_SubTitle_KOREA = "<color=#ffd34c>양대가리</color>: 다 아는 방법이 있지 ㅋㅋ\n<color=#ffd34c>양대가리</color>: 그나저나 병가 냈다며? 몸은 좀 괜찮아? \n<color=#ffd34c>양대가리</color>: 그러게 왜 무리를 하고 그래, 마음 아프게 ㅋㅋ"
L31_1.m_fSubTitleTalkTime = 0.01
L31_1.m_SubTitle_JPN = "<color=#ffd34c>羊頭</color>：調べる方法くらいあるわよｗｗ\n<color=#ffd34c>羊頭</color>：それより、病休だって聞いたけど体調どう？\n<color=#ffd34c>羊頭</color>：そんなに無理しなくてもよかったのに。心が痛むじゃないｗｗ"
L31_1.m_SubTitle_ENG = [[
<color=#ffd34c>Sheep Head</color>: There are ways to know everything lol
<color=#ffd34c>Sheep Head</color>: Anyway, I heard you took sick leave? You doing any better?
<color=#ffd34c>Sheep Head</color>: See? That's what you get for pushing yourself so hard. Breaks my heart haha]]
L31_1.m_SubTitle_TWN = "<color=#ffd34c>羊頭</color>：方法多得是啦嘻嘻\n<color=#ffd34c>羊頭</color>：話說你不是請病假？身體好點了嗎？\n<color=#ffd34c>羊頭</color>：所以說幹嘛那麼逞強，讓人那麼心疼嘻嘻"
L31_1.m_SubTitle_DEU = [[
<color=#ffd34c>Sheep Head</color>: There are ways to know everything lol
<color=#ffd34c>Sheep Head</color>: Anyway, I heard you took sick leave? You doing any better?
<color=#ffd34c>Sheep Head</color>: See? That's what you get for pushing yourself so hard. Breaks my heart haha]]
L31_1.m_SubTitle_FRA = [[
<color=#ffd34c>Sheep Head</color>: There are ways to know everything lol
<color=#ffd34c>Sheep Head</color>: Anyway, I heard you took sick leave? You doing any better?
<color=#ffd34c>Sheep Head</color>: See? That's what you get for pushing yourself so hard. Breaks my heart haha]]
