L28_1 = "SWORD_NPC_ESPR2_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "아시다시피, 현재 학회는 새로운 학회장에 의해, 새로운 질서를 확립하고 있습니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ご存じの通り、今の学会は新任学会長により、新しい秩序を築いている最中です。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "As you know, the Society is currently establishing a new order under the new President."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你也知道，目前學會在新任會長的主導下，正在建立新秩序。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "As you know, the Society is currently establishing a new order under the new President."
L27_1.m_Talk_DEU = L28_1
L28_1 = "As you know, the Society is currently establishing a new order under the new President."
L27_1.m_Talk_FRA = L28_1
