L28_1.m_fWaitTime = 0
L29_1 = "SWORD_NPC_ESPR2_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "내부의 움직임이 결코 표면에 드러나지 않는, 깊고도 깊은 호수처럼……."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "内部の動きが決して表に現れない、深い湖のように……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Like a deep, still lake whose movements never surface..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "內部動向如同深不見底的湖泊，從不浮出水面……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "Like a deep, still lake whose movements never surface..."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Like a deep, still lake whose movements never surface..."
