L42_1 = "마치 이전 학회가 그랬듯, 이들의 활동은 결코 음지에서 머무르지 않아요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "以前の学会がそうだったように、彼らの活動は陰の範囲を越えています。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Just like the former Society, their actions will not remain hidden forever."
