L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "C"
L44_1 = "솔직히 종교학부의 규모와 위상은 학부라고 부르기에도 민망한 수준이잖아?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "正直、昨今の宗教学部の規模とか地位なんて、学部と呼ぶのも恥ずかしいレベルじゃない。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Frankly, calling the Religion Department a \"department\" at all is generous these days."
L43_1.m_Talk_ENG = L44_1
L44_1 = "說實話，宗教學院的規模與地位，就連稱作一個學院都讓人覺得有點尷尬吧？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "Frankly, calling the Religion Department a \"department\" at all is generous these days."
L43_1.m_Talk_DEU = L44_1
