L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "아시다시피, 학회에서의 위상은 단순히 학회원의 머릿수로 결정되는 게 아니죠."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ご存じだと思いますが、学会での地位は単純に学会員の人数で決まるものではありません。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "As you know, status within the Society isn't determined by headcount alone."
L45_1.m_Talk_ENG = L46_1
L46_1 = "如你所知，學院從來就不是單憑學會成員人數決定在學會中的地位。"
