L49_1 = "그리고 학회는 단 한 번도 종교학부가 가진 지식의 가치를 낮게 책정한 적이 없습니다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そして学会は宗教学部が持つ知識の価値を、ただの一度も低く評価したことはありません。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And the Society has never underestimated the value of the knowledge your department holds."
L48_1.m_Talk_ENG = L49_1
L49_1 = "而且學會也從未低估宗教學院持有的知識價值。"
