L26_1 = "이 일련의 사건들이 신의 그릇과 연루되어 있다는 걸, 법학부가 모를 줄 알았습니까?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "この一連の事件が神の器と関係していることに、法学部が気づいてないと思いましたか？"
L25_1.m_Talk_JPN = L26_1
