L32_1 = "그릇과 관련된 모든 문제는 종교학부에 그 책임이 있고……."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "器と関連したすべての問題の責任は宗教学部にあり……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "All matters involving vessels fall under the responsibility of the Religion Department."
