L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "학회의 질서 유지를 위해, 당신들은 반드시 최선을 다해야만 할 겁니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "学会の秩序を守るために、あなた方は必ず最善を尽くさねばなりません。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "And for the sake of maintaining order within the Society, you will be held accountable."
L32_1.m_Talk_ENG = L33_1
L33_1 = "為了維持學會的秩序，你們必須竭盡全力。"
