L37_1 = "내가 졌어. 감춘다고 감췄는데, 상담료를 제법 비싸게 치르고 말았잖아?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "負けたわ。隠したつもりだったのに、高い相談料を払ってしまったわね。"
L36_1.m_Talk_JPN = L37_1
