L38_1 = "命なら聖皇庁を裏切り、この修道院に潜入した時に捨てた。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "I abandoned my life the moment I betrayed Holy Curia and hid in this monastery."
L37_1.m_Talk_ENG = L38_1
L38_1 = "從背叛聖皇廳、躲進這座修道院的那一刻起，我就已經將性命置之度外了。"
L37_1.m_Talk_TWN = L38_1
