L38_1.m_CharStrID = L39_1
L39_1 = "단지 뜻을 이루지 못하고 죽는다면, 오직 그것만이 원통할 뿐이겠지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ただ、志を果たせぬまま倒れるならば、その無念のみが後に残るだろう。"
